mapper.select:
SELECT id, username, password, nickname, email, phone, avatar, role, status, create_time, update_time
FROM `user`
WHERE username = #{username}

SELECT id, username, password, nickname, email, phone, avatar, role, status, create_time, update_time
FROM `user`
WHERE id = #{id}

SELECT id, username, nickname, email, phone, avatar, role, status, create_time, update_time
FROM `user`


        AND (username LIKE CONCAT('%', #{username}, '%') OR nickname LIKE CONCAT('%', #{username}, '%'))


        AND status = #{status}


        AND role = #{role}


ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM `user`


        AND (username LIKE CONCAT('%', #{username}, '%') OR nickname LIKE CONCAT('%', #{username}, '%'))


        AND status = #{status}


        AND role = #{role}
